<script lang="ts">export interface Proposal { title: string; description?: string; status?: string; } export let proposal: Proposal; export let onApprove: (() => void) | undefined = undefined; export let onEdit: (() => void) | undefined = undefined; export let onReject: (() => void) | undefined = undefined;</script>
<article class="proposal"><header><div class="source">{proposal.title.split(" → ")[0]}</div><strong>{proposal.title.includes(" → ") ? proposal.title.split(" → ")[1] : proposal.title}</strong>{#if proposal.status}<span class="status">{proposal.status}</span>{/if}</header>{#if proposal.description}<p>{proposal.description}</p>{/if}{#if onApprove || onEdit || onReject}<footer>{#if onApprove}<button class="primary" on:click={() => onApprove?.()}>Approve</button>{/if}{#if onEdit}<button on:click={() => onEdit?.()}>Edit</button>{/if}{#if onReject}<button on:click={() => onReject?.()}>Reject</button>{/if}</footer>{/if}</article>
<style>
  .proposal { display: grid; gap: 6px; padding: 11px 0; color: var(--color-text); box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--color-text) 7%, transparent); } header, footer { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; } header strong { flex: 1; min-width: 0; font-size: 13px; font-weight: 500; } .source { width: 42px; flex: none; color: var(--color-accent-600, var(--color-accent)); font-size: 9px; letter-spacing: .08em; text-transform: uppercase; } .status, p { color: var(--color-text-muted); font-size: 10.5px; } p { margin: 0; font-family: var(--font-mono); } footer { justify-content: flex-end; margin-top: 3px; } button { padding: 4px 9px; border: 1px solid var(--color-border); border-radius: var(--radius-sm); background: transparent; color: var(--color-text-dim); cursor: pointer; font: 11px var(--font-body); } button:hover { border-color: var(--color-accent); color: var(--color-text); } button.primary { border-color: var(--color-accent); color: var(--color-accent); }
</style>
